mapper.select:
SELECT topic, mastery, quiz_accuracy, study_minutes, wrong_count, quiz_question_count
FROM sa_topic_progress WHERE user_id = #{userId}
ORDER BY update_time DESC LIMIT #{limit}

SELECT w.id, w.question_id, w.topic, w.wrong_count, w.mastered, q.content
FROM sa_wrong_question w
JOIN sa_quiz_question q ON q.id = w.question_id
WHERE w.user_id = #{userId}
ORDER BY w.mastered ASC, w.wrong_count DESC, w.last_wrong_at DESC LIMIT #{limit}

SELECT topic, mastery, quiz_accuracy, study_minutes, wrong_count, quiz_question_count
FROM sa_topic_progress WHERE user_id = #{userId}
ORDER BY mastery ASC, wrong_count DESC LIMIT #{limit}

SELECT id, title, topic, difficulty, status, score, correct_count, wrong_count, create_time
FROM sa_quiz WHERE user_id = #{userId} AND status = 'COMPLETED'
ORDER BY create_time DESC, id DESC LIMIT #{limit}

SELECT id, user_id, type, topic, duration_minutes, source_id, remark, create_time
FROM sa_learning_record WHERE user_id = #{userId}
ORDER BY create_time DESC, id DESC LIMIT #{limit}
